  "check_code": "import json
import sqlite3
from pathlib import Path

TARGETS = {"SC-LR-2025-002", "SC-LR-2025-005"}
CORE_COLUMNS = (
    "supervision_case_id", "supervision_finding", "handling_opinion",
    "case_status", "closed_date", "version_no",
)
PLAN_COLUMNS = (
    "sampling_plan_id", "supervision_case_id", "sampling_type", "sampling_scope",
    "planned_date", "completed_date", "sampling_status", "owner_department_id",
    "created_at", "version_no",
)

def _database_path(ws, backup=False):
    name = "state.db.pinned_backup" if backup else "state.db"
    return Path(ws).resolve().parent / "system" / "fund_supervision_casework" / name

def _connect(ws, backup=False):
    connection = sqlite3.connect(_database_path(ws, backup))
    connection.row_factory = sqlite3.Row
    return connection

def _audit_payloads(connection, supervision_case_id):
    try:
        rows = connection.execute(
            "SELECT request_payload FROM tool_mutation_audit "
            "WHERE operation_name = 'record_supervision_conclusion' AND entity_id = ? ORDER BY audit_id",
            (supervision_case_id,),
        ).fetchall()
    except sqlite3.OperationalError:
        return []
    payloads = []
    for row in rows:
        try:
            payloads.append(json.loads(row["request_payload"]))
        except (TypeError, json.JSONDecodeError):
            continue
    return payloads

def _check_target(ws, expected):
    with _connect(ws) as connection:
        row = connection.execute(
            "SELECT supervision_case_id, supervision_finding, handling_opinion, "
            "case_status, closed_date, version_no FROM supervision_case WHERE supervision_case_id = ?",
            (expected["supervision_case_id"],),
        ).fetchone()
        if row is None:
            return {"score": 0, "detail": "目标案件不存在"}
        actual = dict(row)
        required_state = {
            "supervision_case_id": expected["supervision_case_id"],
            "supervision_finding": expected["supervision_finding"],
            "handling_opinion": expected["handling_opinion"],
            "case_status": "待抽查", "closed_date": None, "version_no": 3,
        }
        if actual != required_state:
            return {"score": 0, "detail": f"案件后态不符: {actual}"}
        matching_audits = [
            payload for payload in _audit_payloads(connection, expected["supervision_case_id"])
            if payload.get("supervision_case_id") == expected["supervision_case_id"]
            and payload.get("supervision_finding") == expected["supervision_finding"]
            and payload.get("handling_opinion") == expected["handling_opinion"]
            and payload.get("case_status") == "待抽查"
            and payload.get("expected_version_no") == 2
            and payload.get("conclusion_review_note_id") == expected["conclusion_review_note_id"]
        ]
        if len(matching_audits) != 1:
            return {"score": 0, "detail": f"未找到唯一且引用原书面核查记录的结论登记审计，匹配数={len(matching_audits)}"}
    return {"score": 1, "detail": "案件后态、原结论保留、版本递增及书面依据引用均正确"}

def check_case_002(ws):
    return _check_target(ws, {
        "supervision_case_id": "SC-LR-2025-002",
        "supervision_finding": "服务不足或提前出院疑点确认",
        "handling_opinion": "医嘱显示计划检查项目未执行即出院，确认存在服务提供不足疑点。",
        "conclusion_review_note_id": "RN-2025-002",
    })

def check_case_005(ws):
    return _check_target(ws, {
        "supervision_case_id": "SC-LR-2025-005",
        "supervision_finding": "病案首页其他诊断或手术操作漏编问题确认",
        "handling_opinion": "手术记录存在清创缝合操作，首页手术操作栏漏填，责成补录并复核结算清单。",
        "conclusion_review_note_id": "RN-2025-005",
    })

def check_other_cases_unchanged(ws):
    column_sql = ", ".join(CORE_COLUMNS)
    placeholders = ",".join("?" for _ in TARGETS)
    query = (
        f"SELECT {column_sql} FROM supervision_case WHERE analysis_period_id = 'PERIOD_2025H1_001' "
        f"AND screening_batch_no = 'SWYB-DRG-LR-2025H1-01' "
        f"AND supervision_case_id NOT IN ({placeholders}) ORDER BY supervision_case_id"
    )
    params = tuple(sorted(TARGETS))
    with _connect(ws) as current, _connect(ws, backup=True) as baseline:
        current_rows = [tuple(row[column] for column in CORE_COLUMNS) for row in current.execute(query, params)]
        baseline_rows = [tuple(row[column] for column in CORE_COLUMNS) for row in baseline.execute(query, params)]
        if current_rows != baseline_rows:
            return {"score": 0, "detail": "非目标案件的结论、意见、状态、结案日期或版本发生变化"}
        plan_query = (
            "SELECT " + ", ".join(PLAN_COLUMNS)
            + " FROM followup_sampling_plan WHERE sampling_plan_id NOT LIKE 'SP-OT-%'"
            + " ORDER BY sampling_plan_id"
        )
        current_plans = [tuple(row[column] for column in PLAN_COLUMNS) for row in current.execute(plan_query)]
        baseline_plans = [tuple(row[column] for column in PLAN_COLUMNS) for row in baseline.execute(plan_query)]
        if current_plans != baseline_plans:
            return {"score": 0, "detail": "抽查计划与原始快照不一致，存在新增、修改或删除计划"}
        try:
            changed_non_targets = current.execute(
                f"SELECT COUNT(*) FROM tool_mutation_audit WHERE operation_name = 'record_supervision_conclusion' "
                f"AND entity_id NOT IN ({placeholders})", params,
            ).fetchone()[0]
        except sqlite3.OperationalError:
            changed_non_targets = 0
        if changed_non_targets:
            return {"score": 0, "detail": "存在针对非目标案件的结论登记操作"}
        try:
            created_or_changed_plans = current.execute(
                "SELECT COUNT(*) FROM tool_mutation_audit WHERE operation_name = 'schedule_followup_sampling'"
            ).fetchone()[0]
        except sqlite3.OperationalError:
            created_or_changed_plans = 0
        if created_or_changed_plans:
            return {"score": 0, "detail": "存在新增或变更抽查计划的操作审计"}
    return {"score": 1, "detail": "本期低倍率非目标案件及全部抽查计划保持原始快照；暂缓案件未被推进"}
